import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  UP,
  DOWN,
  LEFT,
  RIGHT,
  BALL_R,
  BRICK_H,
  BRICK_W,
  resolveBrickCollision,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 500, r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// Issue #1: Brick Bounces

test('brick bounce: hit top face', () => {
  const ball = { x: 100, y: 93, r: 7, vx: 0, vy: 100 };
  const brick = { x: 80, y: 100, w: 40, h: 20 };
  resolveBrickCollision(ball, brick);
  assert.equal(ball.vy, -100, 'vy should flip when hitting top face');
  assert.equal(ball.y, 100 - 7, 'ball should be pushed out to top');
});

test('brick bounce: hit bottom face', () => {
  const ball = { x: 100, y: 113, r: 7, vx: 0, vy: -100 };
  const brick = { x: 80, y: 100, w: 40, h: 20 };
  resolveBrickCollision(ball, brick);
  assert.equal(ball.vy, 100, 'vy should flip when hitting bottom face');
  assert.equal(ball.y, 120 + 7, 'ball should be pushed out to bottom');
});

test('brick bounce: hit left face', () => {
  const ball = { x: 73, y: 110, r: 7, vx: 100, vy: 0 };
  const brick = { x: 80, y: 100, w: 40, h: 20 };
  resolveBrickCollision(ball, brick);
  assert.equal(ball.vx, -100, 'vx should flip when hitting left face');
  assert.equal(ball.x, 80 - 7, 'ball should be pushed out to left');
});

test('brick bounce: hit right face', () => {
  const ball = { x: 127, y: 110, r: 7, vx: -100, vy: 0 };
  const brick = { x: 80, y: 100, w: 40, h: 20 };
  resolveBrickCollision(ball, brick);
  assert.equal(ball.vx, 100, 'vx should flip when hitting right face');
  assert.equal(ball.x, 120 + 7, 'ball should be pushed out to right');
});

test('brick bounce: hit corner (diagonal)', () => {
  const ball = { x: 77, y: 97, r: 7, vx: 100, vy: 100 };
  const brick = { x: 80, y: 100, w: 40, h: 20 };
  // At this position, overlapX is 10 and overlapY is 10.
  resolveBrickCollision(ball, brick);
  assert.equal(ball.vx, -100, 'vx should flip on corner hit');
  assert.equal(ball.vy, -100, 'vy should flip on corner hit');
});

