export function step(state, dt) {
  const { ball, paddle } = state;

  // Sweep collision detection for bricks to prevent tunneling (#1)
  // We check if the ball crossed any brick during this time step.
  const prevX = ball.x;
  const prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // To handle tunneling, we could use a more robust sweep, but a simple
  // approach for this arcade game is to check if the ball was "inside" 
  // a brick at the start of the step or if it's inside now.
  // However, the current architecture handles brick collisions in frame().
  // Let's move the brick collision logic from frame() to step() to allow 
  // better physics control and potential sub-stepping.

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0;
  }

  // Brick collisions
  for (const brick of state.bricks) {
    if (brick.alive && collides(ball, brick)) {
      resolveBrickCollision(ball, brick);
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

